from datetime import datetime
from typing import Dict, List, Optional
from os import makedirs

from taf.config.testline import TestLine
from taf.collectors.core.robot.collector_keywords import CollectorKeywords
from taf.hw.rf_diagnostic_card import rf_diagnostic_card

from taf.rfrl.procedures.resources.python.bts.bts.cloud_bts import CloudBts
from taf.rfrl.procedures.resources.python.bts.components.rmod.cloud_rmod import CloudRmod
from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import pretty_log, log_info, log_debug
from taf.rfrl.procedures.resources.python.bts.utils.errors import ErrorHistory


class LogCollector:
    """ Responsible for configuring, starting and collecting logs from test case execution. """

    def __init__(self):
        self._tl_config: Optional[TestLine] = None
        self._btss: List[CloudBts] = []
        self._logs_main_path: Optional[str] = None
        self._logs_current_path: Optional[str] = None
        self._logs_config: Dict[str, Dict] = {}
        self._collectors = CollectorKeywords()
        self._group_name: Optional[str] = None
        self._lmis: Optional[rf_diagnostic_card] = None

    @property
    def syslogs_path(self) -> Optional[str]:
        """
        Returns absolute path to directory where syslog files are stored.
        If log collection is not configured and logs path is not set then None will be returned.
        """
        return f'{self._logs_current_path}/syslogs' if self._logs_current_path else None

    @property
    def lmis(self) -> Optional[rf_diagnostic_card]:
        """
        Returns rf_diagnostic_card used for managing communication with RMODs via LMI.
        If RMOD logs collection via LMI is not configured then None will be returned.
        """
        return self._lmis

    @property
    def rmods_connected_via_lmi(self) -> List[CloudRmod]:
        """
        Returns RMODs which have open LMI connections.
        If RMOD logs collection via LMI is not configured then empty list will be returned.
        """
        connected_rmods = []

        if self._lmis:
            for bts in self._btss:
                connected_rmods.extend([rmod for rmod in bts.rmods if rmod.serial_number in self._lmis.rmod_connections])

        return connected_rmods

    @pretty_log
    def configure_log_collection(self,
                                 tl_config: TestLine,
                                 btss: List[CloudBts],
                                 logs_path: str,
                                 test_case_name: str,
                                 group_name: str,
                                 syslog: bool = True,
                                 snapshot: bool = True,
                                 rmod_logs: bool = True,
                                 rmod_logs_config_path: Optional[str] = None) -> Dict[str, Dict[str, str]]:
        """
        Configures which logs will be collected and where.
        :param tl_config: configuration of Testline from init file which will be used for logs collection
        :param btss: all BTSs from which logs should be collected
        :param test_case_name: name of currently executed test case; i.e. 'general_siso_auto_cloud_rmods_reset'
        :param logs_path: path to directory where all collected logs should be stored; i.e. '/home/ute/logs'
        :param group_name: name of log group to be used in logs configuration; i.e. 'syslogs'
        :param syslog: defines whether syslog should be collected; defaults to True (syslog will be collected)
        :param snapshot: defines whether snapshots should be collected; defaults to True (snapshots will be collected)
        :param rmod_logs: defines whether RMOD serial logs and snapshots should be collected via LMI; defaults to True (RMOD logs will be collected)
        :param rmod_logs_config_path: absolute path to YAML file with custom configuration of RMOD logs collection;
                                      takes effect only if RMOD logs collection via LMI is enabled;
                                      example of YAML file content can be found in taf.hw.rf_diagnostic_card.examples.custom_setup_example.yaml;
                                      defaults to None (default configuration will be used)
        :return: created logs configuration; i.e. {'syslogs': {'type': 'group',
                                                               'members': 'syslog'},
                                                   'syslog': {'type': 'syslog'},
                                                   'snapshot': {'type': 'snapshot'}}
        """
        if syslog or snapshot or rmod_logs:
            log_info('Configuring logs collection')

        self._tl_config = tl_config
        self._btss = btss
        self._logs_main_path = logs_path
        self._logs_current_path = f'{logs_path}/bts_logs/{datetime.now()}_{test_case_name}'.replace(' ', '_')
        self._group_name = group_name
        self._lmis = None

        logs_config = {}

        if syslog:
            log_debug('Configuring syslog collection')
            logs_config['syslog'] = {'type': 'syslog'}
            logs_config[self._group_name] = {'type': 'group',
                                             'members': 'syslog'}
        if snapshot:
            log_debug('Configuring snapshot collection')
            logs_config['snapshot'] = {'type': 'snapshot'}

        if rmod_logs:
            log_debug('Configuring RMOD logs collection via LMI')
            self._lmis = rf_diagnostic_card()
            self._lmis.prepare_log_directory_and_connection_setup(main_log_directory=f'{self._logs_current_path}/rmod_serial_logs',
                                                                  connection_setup=rmod_logs_config_path)

        self._logs_config = logs_config
        return logs_config

    @pretty_log
    def start_logs_collection(self):
        """
        Prepares environment and starts background logs collection (i.e. syslog, RMOD serial logs) if they were defined in logs configuration.
        """
        if self._logs_config or self._lmis:
            log_info('Starting logs collection', to_console=True)

        if self._group_name in self._logs_config:
            log_debug('Starting log collectors')
            self._collectors.setup_collectors(names=self._group_name)
            self._collectors.start_collectors(names=self._group_name)

        if self._lmis:
            self._start_rmod_serial_logs_collection()

    @pretty_log
    def collect_logs(self, test_result: str, errors: ErrorHistory):
        """
        Collects all logs defined during logs configuration and stores them in logs directory created for currently executed test case.
        If any exception occurs during log collection it will not stop log collection and will be stored in errors history instead.
        If test results is 'FAIL' then all configured logs will be collected.
        If test result is 'PASS' then only following logs (if configured) will be collected:
            * syslog
            * RMOD serial logs
        :param test_result: result of currently executed test case; can be 'PASS' or 'FAIL'
        :param errors: used for collecting errors during logs collection
        """
        if self._logs_config or self._lmis:
            log_info(f'Collecting logs to {self._logs_current_path}', to_console=True)

        error_type = 'Log collection'

        if self._group_name in self._logs_config:
            self._collect_logs_from_collectors(errors, error_type)

        if 'snapshot' in self._logs_config and test_result == 'FAIL':
            self._collect_snapshots(errors, error_type)

        if self._lmis and test_result == 'FAIL':
            self._collect_rmod_snapshots(errors, error_type)

        if self._lmis:
            self._collect_rmod_serial_logs(errors, error_type)

    @pretty_log
    def _start_rmod_serial_logs_collection(self):
        log_debug('Starting RMOD serial logs collection via LMI')
        rmod_configs_with_lmi = []

        for gnb_config in self._tl_config.gnbs:
            for du_config in gnb_config.dus:
                if du_config.fhgws:
                    for fhgw_config in du_config.fhgws:
                        rmod_configs_with_lmi.extend([ru_config for ru_config in fhgw_config.rus if ru_config.lmi])
                if du_config.rus:
                    rmod_configs_with_lmi.extend([ru_config for ru_config in du_config.rus if ru_config.lmi])

        self._lmis.setup_connections(ru_config=rmod_configs_with_lmi)

    @pretty_log
    def _collect_logs_from_collectors(self, errors: ErrorHistory, error_type: str):
        try:
            log_debug('Collecting logs from collectors')
            self._collectors.stop_collectors(names=self._group_name)
            self._collectors.collect_collectors(names=self._group_name,
                                                target_dir=self._logs_current_path)
            self._collectors.teardown_collectors(names=self._group_name)
        except Exception as exc:
            errors.add(error_type=error_type,
                       error_msg=f'Error while collecting logs from collectors. Reason: {exc}')

    @pretty_log
    def _collect_snapshots(self, errors: ErrorHistory, error_type: str):
        snapshots_path = f'{self._logs_current_path}/snapshots'

        for bts_id, bts in enumerate(self._btss):
            for cu in bts.cus:
                try:
                    cu_snapshot_path = f'{snapshots_path}/snapshot_bts_{bts_id}_{cu.name.lower()}'
                    makedirs(cu_snapshot_path)
                    cu.collect_snapshot(path=cu_snapshot_path)
                except Exception as exc:
                    errors.add(error_type=error_type,
                               error_msg=f'Error while collecting snapshot from {cu.name}. Reason: {exc}'.rstrip())

                for du in cu.dus:
                    try:
                        du_snapshot_path = f'{snapshots_path}/snapshot_bts_{bts_id}_{du.name.lower()}'
                        makedirs(du_snapshot_path)
                        du.collect_snapshot(path=du_snapshot_path)
                    except Exception as exc:
                        errors.add(error_type=error_type,
                                   error_msg=f'Error while collecting snapshot from {du.name}. Reason: {exc}'.rstrip())

    @pretty_log
    def _collect_rmod_snapshots(self, errors: ErrorHistory, error_type: str):
        local_snapshots_dir_path = f'{self._logs_current_path}/rmod_snapshots'
        makedirs(local_snapshots_dir_path)

        for rmod in self.rmods_connected_via_lmi:
            try:
                log_info(f'Collecting snapshot from {rmod.name} via LMI', to_console=True)
                is_rmod_reset_required = rmod.du.is_alarm_active(fault_id='10')
                self._lmis.take_snapshot(alias=rmod.serial_number,
                                         reset_rmod=is_rmod_reset_required,
                                         skip_downloading=True,
                                         timeout=300)
                snapshot_path_on_rmod = self._lmis.get_rmod_snapshot_path(alias=rmod.serial_number)
                rmod.download_file(file_path=snapshot_path_on_rmod,
                                   local_dir_path=local_snapshots_dir_path)
                rmod.remove_file(file_path=snapshot_path_on_rmod)
            except Exception as exc:
                errors.add(error_type=error_type,
                           error_msg=f'Error while collecting snapshot from {rmod.name}. Reason: {exc}')

    @pretty_log
    def _collect_rmod_serial_logs(self, errors: ErrorHistory, error_type: str):
        for rmod in self.rmods_connected_via_lmi:
            try:
                log_info(f'Collecting serial logs from {rmod.name} via LMI', to_console=True)
                self._lmis.disconnect(alias=rmod.serial_number)
            except Exception as exc:
                errors.add(error_type=error_type,
                           error_msg=f'Error while collecting serial logs from {rmod.name}. Reason: {exc}')
